//! Minimal 256-bit unsigned integer used by the ABI coder.

use std::cmp::Ordering;
use std::fmt;

/// Error produced when parsing a decimal string.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FromDecStrErr {
    /// A character is not a decimal digit.
    InvalidCharacter,
    /// The number does not fit into 256 bits.
    InvalidLength,
}

/// 256-bit unsigned integer, stored as four 64-bit limbs in big-endian limb order.
#[derive(Clone, Copy, PartialEq, Eq, Default, Hash)]
pub struct U256([u64; 4]);

impl U256 {
    pub const ZERO: U256 = U256([0, 0, 0, 0]);
    pub const MAX: U256 = U256([u64::MAX, u64::MAX, u64::MAX, u64::MAX]);

    pub fn zero() -> Self {
        Self::ZERO
    }

    pub fn is_zero(&self) -> bool {
        self.0.iter().all(|l| *l == 0)
    }

    pub fn from_u64(v: u64) -> Self {
        U256([0, 0, 0, v])
    }

    pub fn from_big_endian(bytes: &[u8; 32]) -> Self {
        let mut limbs = [0u64; 4];
        for (i, limb) in limbs.iter_mut().enumerate() {
            let mut v = 0u64;
            for b in &bytes[i * 8..i * 8 + 8] {
                v = (v << 8) | *b as u64;
            }
            *limb = v;
        }
        U256(limbs)
    }

    pub fn to_big_endian(&self) -> [u8; 32] {
        let mut out = [0u8; 32];
        for (i, limb) in self.0.iter().enumerate() {
            out[i * 8..i * 8 + 8].copy_from_slice(&limb.to_be_bytes());
        }
        out
    }

    /// Multiply by a small integer, reporting overflow.
    pub fn overflowing_mul_u64(&self, by: u64) -> (U256, bool) {
        let mut out = [0u64; 4];
        let mut carry: u128 = 0;
        for i in (0..4).rev() {
            let v = self.0[i] as u128 * by as u128 + carry;
            out[i] = v as u64;
            carry = v >> 64;
        }
        (U256(out), carry != 0)
    }

    pub fn overflowing_add(&self, other: U256) -> (U256, bool) {
        let mut out = [0u64; 4];
        let mut carry = 0u64;
        for i in (0..4).rev() {
            let (s1, c1) = self.0[i].overflowing_add(other.0[i]);
            let (s2, c2) = s1.overflowing_add(carry);
            out[i] = s2;
            carry = (c1 as u64) + (c2 as u64);
        }
        (U256(out), carry != 0)
    }

    pub fn not(&self) -> U256 {
        U256([!self.0[0], !self.0[1], !self.0[2], !self.0[3]])
    }

    /// Two's complement negation (wrapping).
    pub fn neg(&self) -> U256 {
        self.not().overflowing_add(U256::from_u64(1)).0
    }

    /// Parses a decimal string the same way the `uint` crate does.
    pub fn from_dec_str(value: &str) -> Result<U256, FromDecStrErr> {
        let mut res = U256::zero();
        for b in value.bytes().map(|b| b.wrapping_sub(b'0')) {
            if b > 9 {
                return Err(FromDecStrErr::InvalidCharacter);
            }
            let (r, overflow) = res.overflowing_mul_u64(10);
            if overflow {
                return Err(FromDecStrErr::InvalidLength);
            }
            let (r, overflow) = r.overflowing_add(U256::from_u64(b as u64));
            if overflow {
                return Err(FromDecStrErr::InvalidLength);
            }
            res = r;
        }
        Ok(res)
    }

    /// Returns the value as `usize` if it fits.
    pub fn to_usize(&self) -> Option<usize> {
        if self.0[0] != 0 || self.0[1] != 0 || self.0[2] != 0 {
            return None;
        }
        usize::try_from(self.0[3]).ok()
    }
}

impl PartialOrd for U256 {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for U256 {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.cmp(&other.0)
    }
}

impl fmt::LowerHex for U256 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let bytes = self.to_big_endian();
        let mut s = String::with_capacity(64);
        for b in bytes.iter() {
            s.push_str(&format!("{:02x}", b));
        }
        let trimmed = s.trim_start_matches('0');
        if trimmed.is_empty() {
            f.write_str("0")
        } else {
            f.write_str(trimmed)
        }
    }
}

impl fmt::Debug for U256 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:x}", self)
    }
}
