//! Error type of the ABI coder.

use crate::u256::FromDecStrErr;

/// Signed integer parse failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IntParseError {
    Overflow,
    Underflow,
}

/// ABI coder error.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// Invalid entity such as a bad function name.
    #[error("Invalid name: {0}")]
    InvalidName(String),
    /// Invalid data.
    #[error("Invalid data")]
    InvalidData,
    /// Serialization error.
    #[error("Serialization error: {0}")]
    SerdeJson(#[from] serde_json::Error),
    /// Integer parsing error.
    #[error("Integer parsing error: {0}")]
    ParseInt(#[from] std::num::ParseIntError),
    /// Hex string parsing error.
    #[error("Hex parsing error: {0}")]
    Hex(#[from] hex::FromHexError),
    /// Decimal uint parsing error.
    #[error("Uint parse error: {0:?}")]
    Uint(FromDecStrErr),
    /// Decimal int parsing error.
    #[error("int256 parse error: {0:?}")]
    Int(IntParseError),
    /// Other errors.
    #[error("{0}")]
    Other(String),
}

impl From<FromDecStrErr> for Error {
    fn from(e: FromDecStrErr) -> Self {
        Error::Uint(e)
    }
}

pub type Result<T> = std::result::Result<T, Error>;
