//! Function and event param types.

mod reader;

use std::fmt;

pub use reader::Reader;

/// Function and event param types.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ParamType {
    /// Address.
    Address,
    /// Bytes.
    Bytes,
    /// Signed integer.
    Int(usize),
    /// Unsigned integer.
    Uint(usize),
    /// Boolean.
    Bool,
    /// String.
    String,
    /// Array of unknown size.
    Array(Box<ParamType>),
    /// Vector of bytes with fixed size.
    FixedBytes(usize),
    /// Array with fixed size.
    FixedArray(Box<ParamType>, usize),
    /// Tuple containing different types
    Tuple(Vec<ParamType>),
}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            ParamType::Address => write!(f, "address"),
            ParamType::Bytes => write!(f, "bytes"),
            ParamType::FixedBytes(len) => write!(f, "bytes{}", len),
            ParamType::Int(len) => write!(f, "int{}", len),
            ParamType::Uint(len) => write!(f, "uint{}", len),
            ParamType::Bool => write!(f, "bool"),
            ParamType::String => write!(f, "string"),
            ParamType::Array(ref param) => write!(f, "{}[]", param),
            ParamType::FixedArray(ref param, len) => write!(f, "{}[{}]", param, len),
            ParamType::Tuple(ref params) => {
                let s = params.iter().map(|p| p.to_string()).collect::<Vec<_>>().join(",");
                write!(f, "({})", s)
            }
        }
    }
}

impl ParamType {
    /// Returns whether the type is dynamic.
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String | ParamType::Array(_) => true,
            ParamType::FixedArray(elem, _) => elem.is_dynamic(),
            ParamType::Tuple(params) => params.iter().any(|p| p.is_dynamic()),
            _ => false,
        }
    }

    /// Whether empty input is a valid encoding for this type.
    pub fn is_empty_bytes_valid_encoding(&self) -> bool {
        match self {
            ParamType::FixedBytes(len) => *len == 0,
            ParamType::FixedArray(_, len) => *len == 0,
            _ => false,
        }
    }
}

impl<'a> serde::Deserialize<'a> for ParamType {
    fn deserialize<D>(deserializer: D) -> std::result::Result<ParamType, D::Error>
    where
        D: serde::Deserializer<'a>,
    {
        deserializer.deserialize_identifier(ParamTypeVisitor)
    }
}

struct ParamTypeVisitor;

impl<'a> serde::de::Visitor<'a> for ParamTypeVisitor {
    type Value = ParamType;

    fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
        write!(formatter, "a correct name of abi-encodable parameter type")
    }

    fn visit_str<E>(self, value: &str) -> std::result::Result<Self::Value, E>
    where
        E: serde::de::Error,
    {
        Reader::read(value).map_err(|e| serde::de::Error::custom(format!("{:?}", e).as_str()))
    }

    fn visit_string<E>(self, value: String) -> std::result::Result<Self::Value, E>
    where
        E: serde::de::Error,
    {
        self.visit_str(value.as_str())
    }
}
