//! ABI param and parsing for it.

mod lenient;
mod strict;

use std::fmt;

use crate::error::{Error, Result};
use crate::param_type::ParamType;
use crate::u256::U256;

pub use lenient::LenientTokenizer;
pub use strict::StrictTokenizer;

/// Ethereum ABI params.
#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    /// Address.
    Address([u8; 20]),
    /// Vector of bytes with known size.
    FixedBytes(Vec<u8>),
    /// Vector of bytes of unknown size.
    Bytes(Vec<u8>),
    /// Signed integer.
    Int(U256),
    /// Unsigned integer.
    Uint(U256),
    /// Boolean value.
    Bool(bool),
    /// String.
    String(String),
    /// Array with known size.
    FixedArray(Vec<Token>),
    /// Array of params with unknown size.
    Array(Vec<Token>),
    /// Tuple of params of variable types.
    Tuple(Vec<Token>),
}

impl fmt::Display for Token {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            Token::Bool(b) => write!(f, "{}", b),
            Token::String(ref s) => write!(f, "{}", s),
            Token::Address(ref a) => write!(f, "{}", hex::encode(a)),
            Token::Bytes(ref bytes) | Token::FixedBytes(ref bytes) => write!(f, "{}", hex::encode(bytes)),
            Token::Uint(ref i) | Token::Int(ref i) => write!(f, "{:x}", i),
            Token::Array(ref arr) | Token::FixedArray(ref arr) => {
                let s = arr.iter().map(|t| t.to_string()).collect::<Vec<_>>().join(",");
                write!(f, "[{}]", s)
            }
            Token::Tuple(ref s) => {
                let s = s.iter().map(|t| t.to_string()).collect::<Vec<_>>().join(",");
                write!(f, "({})", s)
            }
        }
    }
}

impl Token {
    /// Check whether the type of the token matches the given parameter type.
    pub fn type_check(&self, param_type: &ParamType) -> bool {
        match *self {
            Token::Address(_) => *param_type == ParamType::Address,
            Token::Bytes(_) => *param_type == ParamType::Bytes,
            Token::Int(_) => matches!(*param_type, ParamType::Int(_)),
            Token::Uint(_) => matches!(*param_type, ParamType::Uint(_)),
            Token::Bool(_) => *param_type == ParamType::Bool,
            Token::String(_) => *param_type == ParamType::String,
            Token::FixedBytes(ref bytes) => {
                if let ParamType::FixedBytes(size) = *param_type {
                    size >= bytes.len()
                } else {
                    false
                }
            }
            Token::Array(ref tokens) => {
                if let ParamType::Array(ref param_type) = *param_type {
                    tokens.iter().all(|t| t.type_check(param_type))
                } else {
                    false
                }
            }
            Token::FixedArray(ref tokens) => {
                if let ParamType::FixedArray(ref param_type, size) = *param_type {
                    size == tokens.len() && tokens.iter().all(|t| t.type_check(param_type))
                } else {
                    false
                }
            }
            Token::Tuple(ref tokens) => {
                if let ParamType::Tuple(ref param_type) = *param_type {
                    tokens.iter().zip(param_type.iter()).all(|(t, p)| t.type_check(p))
                } else {
                    false
                }
            }
        }
    }

    /// Check if all the types of the tokens match the given parameter types.
    pub fn types_check(tokens: &[Token], param_types: &[ParamType]) -> bool {
        param_types.len() == tokens.len() && {
            param_types.iter().zip(tokens).all(|(param_type, token)| token.type_check(param_type))
        }
    }

    /// Check if the token is a dynamic type resulting in prefixed encoding
    pub fn is_dynamic(&self) -> bool {
        match self {
            Token::Bytes(_) | Token::String(_) | Token::Array(_) => true,
            Token::FixedArray(tokens) => tokens.iter().any(|token| token.is_dynamic()),
            Token::Tuple(tokens) => tokens.iter().any(|token| token.is_dynamic()),
            _ => false,
        }
    }
}

/// This trait should be used to parse string values as tokens.
pub trait Tokenizer {
    /// Tries to parse a string as a token of given type.
    fn tokenize(param: &ParamType, value: &str) -> Result<Token> {
        match *param {
            ParamType::Address => Self::tokenize_address(value).map(Token::Address),
            ParamType::String => Self::tokenize_string(value).map(Token::String),
            ParamType::Bool => Self::tokenize_bool(value).map(Token::Bool),
            ParamType::Bytes => Self::tokenize_bytes(value).map(Token::Bytes),
            ParamType::FixedBytes(len) => Self::tokenize_fixed_bytes(value, len).map(Token::FixedBytes),
            ParamType::Uint(_) => Self::tokenize_uint(value).map(|b| Token::Uint(U256::from_big_endian(&b))),
            ParamType::Int(_) => Self::tokenize_int(value).map(|b| Token::Int(U256::from_big_endian(&b))),
            ParamType::Array(ref p) => Self::tokenize_array(value, p).map(Token::Array),
            ParamType::FixedArray(ref p, len) => Self::tokenize_fixed_array(value, p, len).map(Token::FixedArray),
            ParamType::Tuple(ref p) => Self::tokenize_struct(value, p).map(Token::Tuple),
        }
    }

    /// Tries to parse a value as a vector of tokens of fixed size.
    fn tokenize_fixed_array(value: &str, param: &ParamType, len: usize) -> Result<Vec<Token>> {
        let result = Self::tokenize_array(value, param)?;
        match result.len() == len {
            true => Ok(result),
            false => Err(Error::InvalidData),
        }
    }

    /// Tried to parse a struct as a vector of tokens
    fn tokenize_struct(value: &str, param: &[ParamType]) -> Result<Vec<Token>> {
        if !value.starts_with('(') || !value.ends_with(')') {
            return Err(Error::InvalidData);
        }

        if value.chars().count() == 2 {
            return Ok(vec![]);
        }

        let mut result = vec![];
        let mut nested = 0isize;
        let mut array_nested = 0isize;
        let mut array_start = 0usize;
        let mut ignore = false;
        let mut skip = false;
        let mut last_item = 1;
        let mut params = param.iter();
        for (pos, ch) in value.chars().enumerate() {
            // inside of an array literal only brackets are significant
            if array_nested != 0 {
                match ch {
                    '[' => array_nested += 1,
                    ']' => {
                        array_nested -= 1;
                        if array_nested == 0 && nested == 0 {
                            let sub = &value[array_start..=pos];
                            let token = Self::tokenize(params.next().ok_or(Error::InvalidData)?, sub)?;
                            result.push(token);
                            skip = !skip;
                        }
                    }
                    _ => (),
                }
                continue;
            }
            if ignore {
                if ch == '"' {
                    ignore = false;
                }
                continue;
            }
            match ch {
                '(' => {
                    nested += 1;
                }
                ')' => {
                    nested -= 1;
                    if skip {
                        skip = false;
                    } else if nested < 0 {
                        return Err(Error::InvalidData);
                    } else if nested == 0 {
                        let sub = &value[last_item..pos];
                        let token = Self::tokenize(params.next().ok_or(Error::InvalidData)?, sub)?;
                        result.push(token);
                        last_item = pos + 1;
                    }
                }
                '"' => {
                    ignore = true;
                }
                ',' if nested == 1 => {
                    if skip {
                        skip = false;
                    } else {
                        let sub = &value[last_item..pos];
                        let token = Self::tokenize(params.next().ok_or(Error::InvalidData)?, sub)?;
                        result.push(token);
                        last_item = pos + 1;
                    }
                }
                '[' => {
                    array_nested = 1;
                    array_start = pos;
                }
                ']' => {
                    if nested == 0 {
                        return Err(Error::InvalidData);
                    }
                    array_nested = -1;
                }
                _ => (),
            }
        }

        if ignore {
            return Err(Error::InvalidData);
        }

        Ok(result)
    }

    /// Tries to parse a value as a vector of tokens.
    fn tokenize_array(value: &str, param: &ParamType) -> Result<Vec<Token>> {
        if !value.starts_with('[') || !value.ends_with(']') {
            return Err(Error::InvalidData);
        }

        if value.chars().count() == 2 {
            return Ok(vec![]);
        }

        let mut result = vec![];
        let mut nested = 0isize;
        let mut tuple_nested = 0isize;
        let mut tuple_start = 0usize;
        let mut ignore = false;
        let mut skip = false;
        let mut last_item = 1;
        for (i, ch) in value.chars().enumerate() {
            // inside of a tuple literal only parentheses are significant
            if tuple_nested != 0 {
                match ch {
                    '(' => tuple_nested += 1,
                    ')' => {
                        tuple_nested -= 1;
                        if tuple_nested == 0 {
                            let sub = &value[tuple_start..=i];
                            let token = Self::tokenize(param, sub)?;
                            result.push(token);
                            skip = !skip;
                        }
                    }
                    _ => (),
                }
                continue;
            }
            if ignore {
                if ch == '"' {
                    ignore = false;
                }
                continue;
            }
            match ch {
                '[' => {
                    nested += 1;
                }
                ']' => {
                    nested -= 1;
                    if skip {
                        skip = false;
                    } else if nested < 0 {
                        return Err(Error::InvalidData);
                    } else if nested == 0 {
                        let sub = &value[last_item..i];
                        let token = Self::tokenize(param, sub)?;
                        result.push(token);
                        last_item = i + 1;
                    }
                }
                '"' => {
                    ignore = true;
                }
                ',' if nested == 1 => {
                    if skip {
                        skip = false;
                    } else {
                        let sub = &value[last_item..i];
                        let token = Self::tokenize(param, sub)?;
                        result.push(token);
                        last_item = i + 1;
                    }
                }
                '(' => {
                    tuple_nested = 1;
                    tuple_start = i;
                }
                ')' => {
                    return Err(Error::InvalidData);
                }
                _ => (),
            }
        }

        if ignore {
            return Err(Error::InvalidData);
        }

        Ok(result)
    }

    /// Tries to parse a value as an address.
    fn tokenize_address(value: &str) -> Result<[u8; 20]>;

    /// Tries to parse a value as a string.
    fn tokenize_string(value: &str) -> Result<String>;

    /// Tries to parse a value as a bool.
    fn tokenize_bool(value: &str) -> Result<bool>;

    /// Tries to parse a value as bytes.
    fn tokenize_bytes(value: &str) -> Result<Vec<u8>>;

    /// Tries to parse a value as bytes.
    fn tokenize_fixed_bytes(value: &str, len: usize) -> Result<Vec<u8>>;

    /// Tries to parse a value as unsigned integer.
    fn tokenize_uint(value: &str) -> Result<[u8; 32]>;

    /// Tries to parse a value as signed integer.
    fn tokenize_int(value: &str) -> Result<[u8; 32]>;
}
