//! Lenient tokenizer: accepts decimal representation of numbers.

use crate::error::{Error, IntParseError, Result};
use crate::token::{StrictTokenizer, Tokenizer};
use crate::u256::U256;

/// Tries to parse string as a token. Does not require string to clearly represent the value.
pub struct LenientTokenizer;

impl Tokenizer for LenientTokenizer {
    fn tokenize_address(value: &str) -> Result<[u8; 20]> {
        StrictTokenizer::tokenize_address(value)
    }

    fn tokenize_string(value: &str) -> Result<String> {
        StrictTokenizer::tokenize_string(value)
    }

    fn tokenize_bool(value: &str) -> Result<bool> {
        StrictTokenizer::tokenize_bool(value)
    }

    fn tokenize_bytes(value: &str) -> Result<Vec<u8>> {
        StrictTokenizer::tokenize_bytes(value)
    }

    fn tokenize_fixed_bytes(value: &str, len: usize) -> Result<Vec<u8>> {
        StrictTokenizer::tokenize_fixed_bytes(value, len)
    }

    fn tokenize_uint(value: &str) -> Result<[u8; 32]> {
        let result = StrictTokenizer::tokenize_uint(value);
        if result.is_ok() {
            return result;
        }

        let uint = U256::from_dec_str(value)?;
        Ok(uint.to_big_endian())
    }

    fn tokenize_int(value: &str) -> Result<[u8; 32]> {
        let result = StrictTokenizer::tokenize_int(value);
        if result.is_ok() {
            return result;
        }

        let abs = U256::from_dec_str(value.trim_start_matches('-'))?;
        // 2^255 - 1
        let max = {
            let mut bytes = [0xffu8; 32];
            bytes[0] = 0x7f;
            U256::from_big_endian(&bytes)
        };
        let int = if value.starts_with('-') {
            if abs.is_zero() {
                return Ok(abs.to_big_endian());
            } else if abs > max.overflowing_add(U256::from_u64(1)).0 {
                return Err(Error::Int(IntParseError::Underflow));
            }
            abs.neg()
        } else {
            if abs > max {
                return Err(Error::Int(IntParseError::Overflow));
            }
            abs
        };
        Ok(int.to_big_endian())
    }
}
