//! ABI decoder.

use crate::error::{Error, Result};
use crate::param_type::ParamType;
use crate::token::Token;
use crate::u256::U256;

struct DecodeResult {
    token: Token,
    new_offset: usize,
}

/// Decodes ABI compliant vector of bytes into vector of tokens described by types param.
pub fn decode(types: &[ParamType], data: &[u8]) -> Result<Vec<Token>> {
    let is_empty_bytes_valid_encoding = types.iter().all(|t| t.is_empty_bytes_valid_encoding());
    if !is_empty_bytes_valid_encoding && data.is_empty() {
        return Err(Error::InvalidName(
            "please ensure the contract and method you're calling exist! \
             failed to decode empty bytes. if you're using jsonrpc this is \
             likely due to jsonrpc returning `0x` in case contract or method \
             don't exist"
                .into(),
        ));
    }

    let mut tokens = Vec::with_capacity(types.len());
    let mut offset = 0;

    for param in types {
        let res = decode_param(param, data, offset)?;
        offset = res.new_offset;
        tokens.push(res.token);
    }

    Ok(tokens)
}

fn peek(data: &[u8], offset: usize, len: usize) -> Result<&[u8]> {
    let end = offset.checked_add(len).ok_or(Error::InvalidData)?;
    if end > data.len() {
        Err(Error::InvalidData)
    } else {
        Ok(&data[offset..end])
    }
}

fn peek_32_bytes(data: &[u8], offset: usize) -> Result<[u8; 32]> {
    peek(data, offset, 32).map(|x| {
        let mut out = [0u8; 32];
        out.copy_from_slice(x);
        out
    })
}

fn round_up_nearest_multiple(value: usize, padding: usize) -> usize {
    (value + padding - 1) / padding * padding
}

fn take_bytes(data: &[u8], offset: usize, len: usize) -> Result<Vec<u8>> {
    let end = offset.checked_add(len).ok_or(Error::InvalidData)?;
    if end > data.len() {
        return Err(Error::InvalidData);
    }
    let _ = round_up_nearest_multiple;
    Ok(data[offset..end].to_vec())
}

fn as_usize(slice: &[u8; 32]) -> Result<usize> {
    U256::from_big_endian(slice).to_usize().ok_or(Error::InvalidData)
}

fn as_bool(slice: &[u8; 32]) -> Result<bool> {
    if !slice[..31].iter().all(|x| *x == 0) {
        return Err(Error::InvalidData);
    }
    Ok(slice[31] == 1)
}

fn decode_param(param: &ParamType, data: &[u8], offset: usize) -> Result<DecodeResult> {
    match *param {
        ParamType::Address => {
            let slice = peek_32_bytes(data, offset)?;
            let mut address = [0u8; 20];
            address.copy_from_slice(&slice[12..]);
            Ok(DecodeResult { token: Token::Address(address), new_offset: offset + 32 })
        }
        ParamType::Int(_) => {
            let slice = peek_32_bytes(data, offset)?;
            Ok(DecodeResult { token: Token::Int(U256::from_big_endian(&slice)), new_offset: offset + 32 })
        }
        ParamType::Uint(_) => {
            let slice = peek_32_bytes(data, offset)?;
            Ok(DecodeResult { token: Token::Uint(U256::from_big_endian(&slice)), new_offset: offset + 32 })
        }
        ParamType::Bool => {
            let b = as_bool(&peek_32_bytes(data, offset)?)?;
            Ok(DecodeResult { token: Token::Bool(b), new_offset: offset + 32 })
        }
        ParamType::FixedBytes(len) => {
            // FixedBytes is anything from bytes1 to bytes32. These values
            // are padded with trailing zeros to fill 32 bytes.
            let bytes = take_bytes(data, offset, len)?;
            Ok(DecodeResult { token: Token::FixedBytes(bytes), new_offset: offset + 32 })
        }
