            let dynamic_offset = as_usize(&peek_32_bytes(data, offset)?)?;
            let len = as_usize(&peek_32_bytes(data, dynamic_offset)?)?;
            let bytes = take_bytes(data, dynamic_offset.checked_add(32).ok_or(Error::InvalidData)?, len)?;
            Ok(DecodeResult {
                token: Token::String(String::from_utf8_lossy(&bytes).into_owned()),
                new_offset: offset + 32,
            })
        }
        ParamType::Array(ref t) => {
            let len_offset = as_usize(&peek_32_bytes(data, offset)?)?;
            let len = as_usize(&peek_32_bytes(data, len_offset)?)?;

            let tail_offset = len_offset.checked_add(32).ok_or(Error::InvalidData)?;
            let tail = data.get(tail_offset..).ok_or(Error::InvalidData)?;

            let mut tokens = Vec::new();
            let mut new_offset = 0;

            for _ in 0..len {
