            let mut tokens = Vec::with_capacity(len);
            for param in t {
                let res = decode_param(param, tail, new_offset)?;
                new_offset = res.new_offset;
                tokens.push(res.token);
            }

            Ok(DecodeResult {
                token: Token::Tuple(tokens),
                new_offset: if is_dynamic { offset + 32 } else { new_offset },
            })
        }
    }
}
