fn set_tuple_components<E: SerdeError>(kind: ParamType, components: Option<Vec<Component>>) -> std::result::Result<ParamType, E> {
    match kind {
        ParamType::Tuple(_) => {
            let components = components.ok_or_else(|| E::missing_field("components"))?;
            let kinds = components
                .into_iter()
                .map(|c| set_tuple_components::<E>(c.kind, c.components))
                .collect::<std::result::Result<Vec<_>, E>>()?;
            Ok(ParamType::Tuple(kinds))
        }
        ParamType::Array(inner) => Ok(ParamType::Array(Box::new(set_tuple_components::<E>(*inner, components)?))),
        ParamType::FixedArray(inner, size) => {
            Ok(ParamType::FixedArray(Box::new(set_tuple_components::<E>(*inner, components)?), size))
        }
        other => Ok(other),
    }
}

