fn long_signature(name: &str, params: &[ParamType]) -> [u8; 32] {
    let types = params.iter().map(|p| p.to_string()).collect::<Vec<_>>().join(",");
    let data: Vec<u8> = From::from(format!("{}({})", name, types).as_str());
    keccak256(&data)
}

impl Function {
    /// Returns all input params of given function.
    fn input_param_types(&self) -> Vec<ParamType> {
        self.inputs.iter().map(|p| p.kind.clone()).collect()
    }

    /// Returns all output params of given function.
    fn output_param_types(&self) -> Vec<ParamType> {
        self.outputs.iter().map(|p| p.kind.clone()).collect()
    }

    /// Prepares ABI function call with given input params.
    pub fn encode_input(&self, tokens: &[Token]) -> Result<Vec<u8>> {
        let params = self.input_param_types();

        if !Token::types_check(tokens, &params) {
            return Err(Error::InvalidData);
        }

        let signed = &long_signature(&self.name, &params)[..4];
        let encoded = encode(tokens);
        Ok(signed.iter().copied().chain(encoded).collect())
    }

    /// Parses the ABI function output to list of tokens.
    pub fn decode_output(&self, data: &[u8]) -> Result<Vec<Token>> {
        decode(&self.output_param_types(), data)
    }

    /// Returns a signature that uniquely identifies this function.
    ///
    /// Examples:
    /// - `functionName()`
    /// - `functionName():(uint256)`
    /// - `functionName(bool):(uint256,string)`
    /// - `functionName(uint256,bytes32):(string,uint256)`
    pub fn signature(&self) -> String {
        let inputs = self.inputs.iter().map(|p| p.kind.to_string()).collect::<Vec<_>>().join(",");
        let outputs = self.outputs.iter().map(|p| p.kind.to_string()).collect::<Vec<_>>().join(",");
        match (inputs.len(), outputs.len()) {
            (_, 0) => format!("{}({})", self.name, inputs),
            (_, _) => format!("{}({}):({})", self.name, inputs, outputs),
        }
    }
}

/// Decoded log param.
#[derive(Debug, Clone, PartialEq)]
pub struct LogParam {
    pub name: String,
    pub value: Token,
}

fn convert_topic_param_type(kind: &ParamType) -> ParamType {
    match kind {
        ParamType::String
        | ParamType::Bytes
        | ParamType::Array(_)
        | ParamType::FixedArray(_, _)
        | ParamType::Tuple(_) => ParamType::FixedBytes(32),
        _ => kind.clone(),
    }
}

impl Event {
    /// Returns all params of the event.
    fn indexed_params(&self, indexed: bool) -> Vec<EventParam> {
        self.inputs.iter().filter(|p| p.indexed == indexed).cloned().collect()
    }

    /// Event signature
    pub fn signature(&self) -> [u8; 32] {
        long_signature(&self.name, &self.inputs.iter().map(|p| p.kind.clone()).collect::<Vec<_>>())
    }

    /// Textual representation of the event signature.
    pub fn text_signature(&self) -> String {
        let inputs = self.inputs.iter().map(|p| p.kind.to_string()).collect::<Vec<_>>().join(",");
        format!("{}({})", self.name, inputs)
    }

    /// Parses `RawLog` and retrieves all log params from it.
    pub fn parse_log(&self, topics: Vec<[u8; 32]>, data: Vec<u8>) -> Result<Vec<LogParam>> {
        let topics_len = topics.len();
        // obtains all params info
        let topic_params = self.indexed_params(true);
        let data_params = self.indexed_params(false);
        // then take first topic if event is not anonymous
        let to_skip = if self.anonymous {
            0
        } else {
            // verify
            let event_signature = topics.first().ok_or(Error::InvalidData)?;
            if event_signature != &self.signature() {
                return Err(Error::InvalidData);
            }
            1
        };

        let topic_types = topic_params.iter().map(|p| convert_topic_param_type(&p.kind)).collect::<Vec<ParamType>>();

        let flat_topics = topics.into_iter().skip(to_skip).flat_map(|t| t.to_vec()).collect::<Vec<u8>>();

        let topic_tokens = decode(&topic_types, &flat_topics)?;

        // topic may be only a 32 bytes encoded token
        if topic_tokens.len() != topics_len - to_skip {
            return Err(Error::InvalidData);
        }

        let topics_named_tokens = topic_params.into_iter().map(|p| p.name).zip(topic_tokens);

        let data_types = data_params.iter().map(|p| p.kind.clone()).collect::<Vec<ParamType>>();

        let data_tokens = decode(&data_types, &data)?;

        let data_named_tokens = data_params.into_iter().map(|p| p.name).zip(data_tokens);

        let named_tokens = topics_named_tokens.chain(data_named_tokens).collect::<HashMap<String, Token>>();

        let decoded_params = self
            .inputs
            .iter()
            .map(|p| LogParam { name: p.name.clone(), value: named_tokens[&p.name].clone() })
            .collect();

        Ok(decoded_params)
    }
}
