// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

struct Colorizer {
    enabled: bool,
}

impl Colorizer {
    fn for_stderr() -> Self {
        let is_tty = std::io::stderr().is_terminal();
        let dumb = std::env::var("TERM").ok() == Some(String::from("dumb"));
        Colorizer { enabled: is_tty && !dumb }
    }

    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_owned()
        }
    }

    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_owned()
        }
    }

    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_owned()
        }
    }
}

/// Always colored "good" formatting (used by the did-you-mean suffix).
fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

// ---------------------------------------------------------------------------
// Definitions
