/// Argument definition.
#[derive(Debug, Clone)]
pub struct Arg {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub help: Option<&'static str>,
    pub long_help: Option<&'static str>,
    pub takes_value: bool,
    pub multiple: bool,
    pub num_vals: Option<usize>,
    pub val_names: Vec<&'static str>,
    pub allow_hyphen_values: bool,
    pub required: bool,
    pub positional: bool,
}

impl Arg {
    pub fn new(name: &'static str) -> Self {
        Arg {
            name,
            short: None,
            long: None,
            help: None,
            long_help: None,
            takes_value: false,
            multiple: false,
            num_vals: None,
            val_names: Vec::new(),
            allow_hyphen_values: false,
            required: false,
            positional: false,
        }
    }

    pub fn short(mut self, s: char) -> Self {
        self.short = Some(s);
        self
    }

    pub fn long(mut self, l: &'static str) -> Self {
        self.long = Some(l);
        self
    }

    pub fn help(mut self, h: &'static str) -> Self {
        self.help = Some(h);
        self
    }

    pub fn long_help(mut self, h: &'static str) -> Self {
        self.long_help = Some(h);
        self
    }

    pub fn takes_value(mut self, v: bool) -> Self {
        self.takes_value = v;
        self
    }

    pub fn multiple(mut self, v: bool) -> Self {
        self.multiple = v;
        self
    }

    pub fn number_of_values(mut self, n: usize) -> Self {
        self.num_vals = Some(n);
        self.takes_value = true;
        self
    }

    pub fn value_names(mut self, names: &[&'static str]) -> Self {
        self.val_names = names.to_vec();
        self.takes_value = true;
        if names.len() > 1 {
            self.num_vals = Some(names.len());
        }
        self
    }

    pub fn allow_hyphen_values(mut self, v: bool) -> Self {
        self.allow_hyphen_values = v;
        self
    }

    pub fn required(mut self, v: bool) -> Self {
        self.required = v;
        self
    }

    pub fn positional(mut self) -> Self {
        self.positional = true;
        self.takes_value = true;
        self
    }

    fn has_switch(&self) -> bool {
        self.short.is_some() || self.long.is_some()
    }

    fn is_flag(&self) -> bool {
        !self.positional && !self.takes_value
    }

    fn is_opt(&self) -> bool {
        !self.positional && self.takes_value
    }

    /// Representation used in usage strings and error messages.
    fn to_display(&self) -> String {
        if self.positional {
            format!("<{}>{}", self.name, if self.multiple { "..." } else { "" })
        } else if self.takes_value {
            let mut s = match (self.long, self.short) {
                (Some(l), _) => format!("--{} ", l),
                (None, Some(c)) => format!("-{} ", c),
                (None, None) => String::new(),
            };
            s.push_str(&self.values_display());
            s
        } else if let Some(l) = self.long {
            format!("--{}", l)
        } else {
            format!("-{}", self.short.unwrap_or('?'))
        }
    }

    fn values_display(&self) -> String {
        let mut s = String::new();
        if !self.val_names.is_empty() {
            let parts: Vec<String> = self.val_names.iter().map(|v| format!("<{}>", v)).collect();
            s.push_str(&parts.join(" "));
            if self.multiple && self.val_names.len() == 1 {
                s.push_str("...");
            }
        } else if let Some(num) = self.num_vals {
            let parts: Vec<String> = (0..num).map(|_| format!("<{}>", self.name)).collect();
            s.push_str(&parts.join(" "));
            if self.multiple && num == 1 {
                s.push_str("...");
            }
        } else {
            s.push_str(&format!("<{}>{}", self.name, if self.multiple { "..." } else { "" }));
        }
        s
    }
}

/// Application / subcommand definition.
#[derive(Debug, Clone)]
pub struct App {
    pub name: String,
    pub bin_name: Option<String>,
    pub version: Option<&'static str>,
    pub about: Option<&'static str>,
    pub args: Vec<Arg>,
    pub subcommands: Vec<App>,
    pub subcommand_required_else_help: bool,
}

impl App {
    pub fn new(name: &str) -> Self {
        App {
            name: name.to_owned(),
            bin_name: None,
            version: None,
            about: None,
            args: Vec::new(),
            subcommands: Vec::new(),
            subcommand_required_else_help: false,
        }
    }

    pub fn version(mut self, v: &'static str) -> Self {
        self.version = Some(v);
        self
    }

    pub fn about(mut self, a: &'static str) -> Self {
        self.about = Some(a);
        self
    }

    pub fn arg(mut self, a: Arg) -> Self {
        self.args.push(a);
        self
    }

    pub fn subcommand(mut self, s: App) -> Self {
        self.subcommands.push(s);
        self
    }

    pub fn subcommand_required_else_help(mut self, v: bool) -> Self {
        self.subcommand_required_else_help = v;
        self
    }

    fn flags(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.is_flag())
    }

    fn opts(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.is_opt())
    }

    fn positionals(&self) -> impl Iterator<Item = &Arg> {
        self.args.iter().filter(|a| a.positional)
    }

    fn has_args(&self) -> bool {
        !self.args.is_empty()
    }

    fn find_arg(&self, name: &str) -> Option<&Arg> {
        self.args.iter().find(|a| a.name == name)
    }

    fn find_opt_by_short(&self, c: char) -> Option<&Arg> {
        self.opts().find(|a| a.short == Some(c))
    }

    fn find_flag_by_short(&self, c: char) -> Option<&Arg> {
        self.flags().find(|a| a.short == Some(c))
    }

    fn find_opt_by_long(&self, l: &str) -> Option<&Arg> {
        self.opts().find(|a| a.long == Some(l))
    }

    fn find_flag_by_long(&self, l: &str) -> Option<&Arg> {
        self.flags().find(|a| a.long == Some(l))
    }

    fn contains_long(&self, l: &str) -> bool {
        self.args.iter().any(|a| a.long == Some(l))
    }

    fn contains_short(&self, c: char) -> bool {
        self.args.iter().any(|a| a.short == Some(c))
    }

    fn display_name(&self) -> &str {
        self.bin_name.as_deref().unwrap_or(&self.name)
    }

    /// Adds the implicit help/version flags and the `help` subcommand.
    fn create_help_and_version(&mut self) {
        if !self.contains_long("help") {
            let short = if !self.contains_short('h') { Some('h') } else { None };
            let mut arg = Arg::new("hclap_help").long("help").help("Prints help information");
            arg.short = short;
            self.args.push(arg);
        }
        if !self.contains_long("version") {
            let short = if !self.contains_short('V') { Some('V') } else { None };
            let mut arg = Arg::new("vclap_version").long("version").help("Prints version information");
            arg.short = short;
            self.args.push(arg);
        }
        if !self.subcommands.is_empty() && !self.subcommands.iter().any(|s| s.name == "help") {
            self.subcommands.push(App::new("help").about("Prints this message or the help of the given subcommand(s)"));
        }
    }

    fn use_long_help(&self) -> bool {
        self.args.iter().any(|a| a.long_help.is_some())
    }
}

// ---------------------------------------------------------------------------
// Matches
// ---------------------------------------------------------------------------

#[derive(Debug, Default, Clone)]
pub struct MatchedArg {
    pub occurs: u64,
    pub vals: Vec<String>,
}

#[derive(Debug, Default, Clone)]
pub struct Matches {
    args: Vec<(&'static str, MatchedArg)>,
    subcommand: Option<(String, Box<Matches>)>,
}

impl Matches {
    fn get(&self, name: &str) -> Option<&MatchedArg> {
        self.args.iter().find(|(n, _)| *n == name).map(|(_, m)| m)
    }

    fn entry(&mut self, name: &'static str) -> &mut MatchedArg {
        if let Some(pos) = self.args.iter().position(|(n, _)| *n == name) {
            &mut self.args[pos].1
        } else {
            self.args.push((name, MatchedArg::default()));
            &mut self.args.last_mut().unwrap().1
        }
    }

    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    fn insert(&mut self, name: &'static str) {
        self.entry(name);
    }

    fn inc_occurrence_of(&mut self, name: &'static str) {
        self.entry(name).occurs += 1;
    }

    fn add_val_to(&mut self, name: &'static str, val: &str) {
        self.entry(name).vals.push(val.to_owned());
    }

    fn arg_names(&self) -> Vec<&'static str> {
        self.args.iter().map(|(n, _)| *n).collect()
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.contains(name)
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.get(name).and_then(|m| m.vals.first()).map(|s| s.as_str())
    }

    pub fn values_of(&self, name: &str) -> Vec<String> {
        self.get(name).map(|m| m.vals.clone()).unwrap_or_default()
    }

    pub fn subcommand(&self) -> Option<(&str, &Matches)> {
        self.subcommand.as_ref().map(|(n, m)| (n.as_str(), m.as_ref()))
    }
}

// ---------------------------------------------------------------------------
// Errors / output
// ---------------------------------------------------------------------------

/// Something that terminates the program: a help/version message or an error.
#[derive(Debug)]
pub struct Exit {
    pub message: String,
    pub use_stderr: bool,
}

impl Exit {
    fn error(message: String) -> Self {
        Exit { message, use_stderr: true }
    }

    fn stdout(message: String) -> Self {
        Exit { message, use_stderr: false }
    }

    pub fn exit(&self) -> ! {
        if self.use_stderr {
            let stderr = std::io::stderr();
            let mut lock = stderr.lock();
            let _ = writeln!(lock, "{}", self.message);
            let _ = lock.flush();
            std::process::exit(1);
        }
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = writeln!(lock, "{}", self.message);
        let _ = lock.flush();
        std::process::exit(0)
    }
}

type ParseRes<T> = Result<T, Exit>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ParseResult {
    Flag,
    Opt(&'static str),
    ValuesDone,
    NotFound,
}

fn err_unknown_argument(arg: &str, did_you_mean: &str, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
        c.error("error:"),
        c.warning(arg),
        if did_you_mean.is_empty() { "\n".to_owned() } else { format!("{}\n", did_you_mean) },
        usage,
        c.good("--help")
    ))
}

fn err_invalid_subcommand(subcmd: &str, did_you_mean: &str, name: &str, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The subcommand '{}' wasn't recognized\n\t\
         Did you mean '{}'?\n\n\
         If you believe you received this message in error, try \
         re-running with '{} {} {}'\n\n\
         {}\n\n\
         For more information try {}",
        c.error("error:"),
        c.warning(subcmd),
        c.good(did_you_mean),
        name,
        c.good("--"),
        subcmd,
        usage,
        c.good("--help")
    ))
}

fn err_unrecognized_subcommand(subcmd: &str, name: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The subcommand '{}' wasn't recognized\n\n\
         {}\n\t\
         {} help <subcommands>...\n\n\
         For more information try {}",
        c.error("error:"),
        c.warning(subcmd),
        c.warning("USAGE:"),
        name,
        c.good("--help")
    ))
}

fn err_empty_value(arg: &Arg, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The argument '{}' requires a value but none was supplied\n\n\
         {}\n\n\
         For more information try {}",
        c.error("error:"),
        c.warning(&arg.to_display()),
        usage,
        c.good("--help")
    ))
}

fn err_wrong_number_of_values(arg: &Arg, num_vals: usize, curr_vals: usize, suffix: &str, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The argument '{}' requires {} values, but {} w{} provided\n\n\
         {}\n\n\
         For more information try {}",
        c.error("error:"),
        c.warning(&arg.to_display()),
        num_vals,
        curr_vals,
        suffix,
        usage,
        c.good("--help")
    ))
}

fn err_unexpected_multiple_usage(arg: &Arg, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n\
         {}\n\n\
         For more information try {}",
        c.error("error:"),
        c.warning(&arg.to_display()),
        usage,
        c.good("--help")
    ))
}

fn err_missing_required_argument(required: &str, usage: &str) -> Exit {
    let c = Colorizer::for_stderr();
    Exit::error(format!(
        "{} The following required arguments were not provided:{}\n\n\
         {}\n\n\
         For more information try {}",
        c.error("error:"),
        required,
        usage,
        c.good("--help")
    ))
}

// ---------------------------------------------------------------------------
// Usage generation
// ---------------------------------------------------------------------------

fn needs_flags_tag(app: &App) -> bool {
    for f in app.flags() {
        if let Some(l) = f.long {
            if l == "help" || l == "version" {
                continue;
            }
        }
        return true;
    }
    false
}

/// Builds the list of required/used arguments as displayed in usage strings.
fn get_required_usage_from(app: &App, reqs: &[&str], matcher: Option<&Matches>) -> Vec<String> {
    let mut desc_reqs: Vec<&str> = reqs.to_vec();
    desc_reqs.sort();
    desc_reqs.dedup();

    let mut ret_val = Vec::new();

    // positionals first, in index order
    for p in app.positionals() {
        if !desc_reqs.contains(&p.name) {
            continue;
        }
        if let Some(m) = matcher {
            if m.contains(p.name) {
                continue;
            }
        }
        ret_val.push(p.to_display());
    }

    for name in desc_reqs.iter() {
        let arg = match app.find_arg(name) {
            Some(a) if !a.positional => a,
            _ => continue,
        };
        if let Some(m) = matcher {
            if m.contains(name) {
                continue;
            }
        }
        ret_val.push(arg.to_display());
    }
    ret_val
}

fn create_help_usage(app: &App, incl_reqs: bool) -> String {
    let mut usage = String::new();
    usage.push_str(app.display_name());

    let req_string = if incl_reqs {
        let mut reqs: Vec<&str> = app.args.iter().filter(|a| a.required).map(|a| a.name).collect();
        reqs.sort();
        reqs.dedup();
        get_required_usage_from(app, &reqs, None).iter().fold(String::new(), |a, s| a + &format!(" {}", s))
    } else {
        String::new()
    };

    if needs_flags_tag(app) {
        usage.push_str(" [FLAGS]");
    }
    if app.opts().any(|o| !o.required) {
        usage.push_str(" [OPTIONS]");
    }

    usage.push_str(&req_string);

    // places a '--' in the usage string if there are args and options supporting multiple values
    if app.opts().any(|o| o.multiple) && app.positionals().any(|p| !p.required) && app.subcommands.is_empty() {
        usage.push_str(" [--]");
    }

    if app.positionals().any(|p| !p.required) {
        let not_req: Vec<&Arg> = app.positionals().filter(|p| !p.required).collect();
        if not_req.len() > 1 {
            usage.push_str(" [ARGS]");
        } else if not_req.len() == 1 && incl_reqs {
            let pos = not_req[0];
            usage.push_str(&format!(" [{}]{}", pos.name, if pos.multiple { "..." } else { "" }));
        }
    }

    if !app.subcommands.is_empty() && incl_reqs {
        if app.subcommand_required_else_help {
            usage.push_str(" <SUBCOMMAND>");
        } else {
            usage.push_str(" [SUBCOMMAND]");
        }
    }
    usage
}

fn create_smart_usage(app: &App, used: &[&str]) -> String {
    let mut usage = String::new();
    let mut hs: Vec<&str> = app.args.iter().filter(|a| a.required).map(|a| a.name).collect();
    hs.extend_from_slice(used);

    let r_string = get_required_usage_from(app, &hs, None).iter().fold(String::new(), |acc, s| acc + &format!(" {}", s));

    usage.push_str(app.display_name());
    usage.push_str(&r_string);
    usage
}

fn create_usage_no_title(app: &App, used: &[&str]) -> String {
    if used.is_empty() {
        create_help_usage(app, true)
    } else {
        create_smart_usage(app, used)
    }
}

fn create_usage_with_title(app: &App, used: &[&str]) -> String {
    format!("USAGE:\n    {}", create_usage_no_title(app, used))
}

fn create_error_usage(app: &App, matcher: &Matches, extra: Option<&str>) -> String {
    let mut args: Vec<&str> = matcher
        .arg_names()
        .into_iter()
        .filter(|n| match app.find_arg(n) {
            Some(a) if a.is_opt() => !a.required,
            Some(a) if a.positional => false,
            _ => true,
        })
        .collect();
    if let Some(r) = extra {
        args.push(r);
    }
    create_usage_with_title(app, &args)
}

// ---------------------------------------------------------------------------
// Help generation
// ---------------------------------------------------------------------------

struct HelpWriter {
    out: String,
    longest: usize,
    use_long: bool,
}

impl HelpWriter {
    fn write_bin_name(&mut self, app: &App) {
        match app.bin_name.as_ref() {
            Some(bn) if bn.contains(' ') => self.out.push_str(&bn.replace(' ', "-")),
            _ => self.out.push_str(&app.name),
        }
    }

    fn write_default_help(&mut self, app: &App) {
        self.write_bin_name(app);
        self.out.push(' ');
        self.out.push_str(app.version.unwrap_or(""));
        self.out.push('\n');
        if let Some(about) = app.about {
            self.out.push_str(about);
            self.out.push('\n');
        }
        self.out.push_str("\nUSAGE:");
        self.out.push_str(&format!("\n{}{}\n\n", TAB, create_usage_no_title(app, &[])));

        let flags = app.flags().count() > 0;
        let pos = app.positionals().count() > 0;
        let opts = app.opts().count() > 0;
        let subcmds = !app.subcommands.is_empty();

        let mut first = true;
        if flags {
            self.out.push_str("FLAGS:\n");
            let args: Vec<&Arg> = app.flags().collect();
            self.write_args(&args);
            first = false;
        }
        if opts {
            if !first {
                self.out.push_str("\n\n");
            }
            self.out.push_str("OPTIONS:\n");
            let args: Vec<&Arg> = app.opts().collect();
            self.write_args(&args);
            first = false;
        }
        if pos {
            if !first {
                self.out.push_str("\n\n");
            }
            self.out.push_str("ARGS:\n");
            let args: Vec<&Arg> = app.positionals().collect();
            self.write_args_unsorted(&args);
            first = false;
        }
        if subcmds {
            if !first {
                self.out.push_str("\n\n");
            }
            self.out.push_str("SUBCOMMANDS:\n");
            self.write_subcommands(app);
        }
    }

    fn write_args(&mut self, args: &[&Arg]) {
        self.longest = 2;
        let mut btm: BTreeMap<&str, &Arg> = BTreeMap::new();
        for arg in args {
            self.longest = std::cmp::max(self.longest, arg.to_display().chars().count());
            btm.insert(arg.name, arg);
        }
        let mut first = true;
        for arg in btm.values() {
            if first {
                first = false;
            } else {
                self.out.push('\n');
            }
            self.write_arg(arg);
        }
    }

    fn write_args_unsorted(&mut self, args: &[&Arg]) {
        self.longest = 2;
        for arg in args {
            self.longest = std::cmp::max(self.longest, arg.to_display().chars().count());
        }
        let mut first = true;
        for arg in args {
            if first {
                first = false;
            } else {
                self.out.push('\n');
            }
            self.write_arg(arg);
        }
    }

    fn write_arg(&mut self, arg: &Arg) {
        // short
        self.out.push_str(TAB);
        if let Some(s) = arg.short {
            self.out.push_str(&format!("-{}", s));
        } else if arg.has_switch() {
            self.out.push_str(TAB);
        }
        // long
        if arg.has_switch() {
            if arg.takes_value {
                if let Some(l) = arg.long {
                    if arg.short.is_some() {
                        self.out.push_str(", ");
                    }
                    self.out.push_str(&format!("--{}", l));
                }
                self.out.push(' ');
            } else if let Some(l) = arg.long {
                if arg.short.is_some() {
                    self.out.push_str(", ");
                }
                self.out.push_str(&format!("--{}", l));
            }
        }
        // values
        if arg.takes_value && arg.has_switch() {
            self.out.push_str(&arg.values_display());
        }
        // padding
        let self_len = arg.to_display().chars().count();
        if arg.has_switch() {
            let mut spcs = self.longest - self_len;
            if arg.long.is_some() {
                spcs += 4;
            } else {
                spcs += 8;
            }
            self.out.push_str(&" ".repeat(spcs));
        } else {
            self.out.push_str(&" ".repeat(self.longest + 4 - self_len));
        }
        // help
        self.write_help_text(arg);
    }

    fn write_help_text(&mut self, arg: &Arg) {
        let h = if self.use_long {
            arg.long_help.or(arg.help).unwrap_or("")
        } else {
            arg.help.or(arg.long_help).unwrap_or("")
        };
        let nlh = self.use_long;
        if nlh {
            self.out.push_str(&format!("\n{}{}{}", TAB, TAB, TAB));
        }
        let mut lines = h.lines();
        if let Some(part) = lines.next() {
            self.out.push_str(part);
        }
        for part in lines {
            self.out.push('\n');
            if nlh {
                self.out.push_str(&format!("{}{}{}", TAB, TAB, TAB));
            } else if arg.has_switch() {
                self.out.push_str(&" ".repeat(self.longest + 12));
            } else {
                self.out.push_str(&" ".repeat(self.longest + 8));
            }
            self.out.push_str(part);
        }
        if !h.contains('\n') && nlh {
            self.out.push('\n');
        }
    }

    fn write_subcommands(&mut self, app: &App) {
        self.longest = 2;
        let mut btm: BTreeMap<&str, &App> = BTreeMap::new();
        for sc in &app.subcommands {
            self.longest = std::cmp::max(self.longest, sc.name.chars().count());
            btm.insert(&sc.name, sc);
        }
        let mut first = true;
        for sc in btm.values() {
            if first {
                first = false;
            } else {
                self.out.push('\n');
            }
            self.out.push_str(TAB);
            self.out.push_str(&sc.name);
            self.out.push_str(&" ".repeat(self.longest + 4 - sc.name.chars().count()));
            if let Some(about) = sc.about {
                if self.use_long {
                    self.out.push_str(&format!("\n{}{}{}", TAB, TAB, TAB));
                }
                self.out.push_str(about);
                if self.use_long {
                    self.out.push('\n');
                }
            }
        }
    }
}

fn render_help(app: &App, use_long: bool) -> String {
    let mut w = HelpWriter { out: String::new(), longest: 0, use_long };
    w.write_default_help(app);
    w.out
}

fn render_version(app: &App) -> String {
    let ver = app.version.unwrap_or("");
    match app.bin_name.as_ref() {
        Some(bn) if bn.contains(' ') => format!("{} {}", bn.replace(' ', "-"), ver),
        _ => format!("{} {}", app.name, ver),
    }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

struct Parser<'a> {
    app: &'a mut App,
    trailing_values: bool,
}

impl<'a> Parser<'a> {
    fn is_new_arg(&self, arg: &str, needs_val_of: ParseResult) -> bool {
        let arg_allows_tac = match needs_val_of {
            ParseResult::Opt(name) => self.app.find_arg(name).map(|o| o.allow_hyphen_values).unwrap_or(false),
            ParseResult::ValuesDone => return true,
            _ => false,
        };

        let ret = if arg.starts_with("--") {
            if arg.len() == 2 && !arg_allows_tac {
                return true;
            } else if arg_allows_tac {
                return false;
            }
            true
        } else if arg.starts_with('-') {
            arg.len() != 1
        } else {
            false
        };

        ret && !arg_allows_tac
    }

    fn possible_subcommand(&self, arg: &str) -> Option<String> {
        self.app.subcommands.iter().find(|s| s.name == arg).map(|s| s.name.clone())
    }

    fn sc_names(&self) -> Vec<&str> {
        self.app.subcommands.iter().map(|s| s.name.as_str()).collect()
    }

    fn help(&self, use_long: bool) -> Exit {
        let use_long = use_long && self.app.use_long_help();
        Exit::stdout(render_help(self.app, use_long))
    }

    fn version(&self) -> Exit {
        Exit::stdout(render_version(self.app))
    }

    fn add_val_to_arg(&self, arg: &Arg, val: &str, matcher: &mut Matches) -> ParseResult {
        matcher.add_val_to(arg.name, val);
        if self.needs_more_vals(arg, matcher) {
            ParseResult::Opt(arg.name)
        } else {
            ParseResult::ValuesDone
        }
    }

    fn needs_more_vals(&self, arg: &Arg, matcher: &Matches) -> bool {
        if let Some(ma) = matcher.get(arg.name) {
            if let Some(num) = arg.num_vals {
                return if arg.multiple { ma.vals.len() % num != 0 } else { num != ma.vals.len() };
            }
            return arg.multiple;
        }
        true
    }

    fn parse_opt(&self, val: Option<&str>, opt: &Arg, matcher: &mut Matches) -> ParseResult {
        let mut has_eq = false;
        let no_val = val.is_none();

        if let Some(fv) = val {
            has_eq = fv.starts_with('=');
            let v = fv.trim_start_matches('=');
            self.add_val_to_arg(opt, v, matcher);
        }

        matcher.inc_occurrence_of(opt.name);

        if no_val || (opt.multiple && !has_eq && self.needs_more_vals(opt, matcher)) {
            return ParseResult::Opt(opt.name);
        }
        ParseResult::ValuesDone
    }

    fn parse_flag(&self, flag: &Arg, matcher: &mut Matches) -> ParseResult {
        matcher.inc_occurrence_of(flag.name);
        ParseResult::Flag
    }

    fn check_for_help_and_version_str(&self, arg: &str) -> ParseRes<()> {
        if arg == "help" {
            return Err(self.help(true));
        }
        if arg == "version" {
            return Err(self.version());
        }
        Ok(())
    }

    fn check_for_help_and_version_char(&self, arg: char) -> ParseRes<()> {
        if let Some(h) = self.app.find_flag_by_long("help").and_then(|f| f.short) {
            if arg == h {
                return Err(self.help(false));
            }
        }
        if let Some(v) = self.app.find_flag_by_long("version").and_then(|f| f.short) {
            if arg == v {
                return Err(self.version());
            }
        }
        Ok(())
    }

    fn parse_long_arg(&mut self, matcher: &mut Matches, full_arg: &str) -> ParseRes<ParseResult> {
        let mut val = None;
        let arg = if full_arg.contains('=') {
            let trimmed = full_arg.trim_start_matches('-');
            let idx = trimmed.find('=').unwrap();
            val = Some(&trimmed[idx..]);
            &trimmed[..idx]
        } else {
            full_arg.trim_start_matches('-')
        };

        if let Some(opt) = self.app.find_opt_by_long(arg).cloned() {
            let ret = self.parse_opt(val, &opt, matcher);
            return Ok(ret);
        } else if let Some(flag) = self.app.find_flag_by_long(arg).cloned() {
            self.check_for_help_and_version_str(arg)?;
            self.parse_flag(&flag, matcher);
            return Ok(ParseResult::Flag);
        }

        self.did_you_mean_error(arg, matcher).map(|_| ParseResult::NotFound)
    }

    fn did_you_mean_error(&self, arg: &str, matcher: &mut Matches) -> ParseRes<()> {
        let longs: Vec<&str> = self.app.args.iter().filter_map(|a| a.long).collect();
        let suffix = match did_you_mean(arg, longs.iter().copied()) {
            Some(candidate) => {
                let suffix = format!("\n\tDid you mean {}{}?", always_good("--"), always_good(candidate));
                (suffix, Some(candidate))
            }
            None => (String::new(), None),
        };

        if let Some(name) = suffix.1 {
            if let Some(opt) = self.app.find_opt_by_long(name) {
                matcher.insert(opt.name);
            } else if let Some(flg) = self.app.find_flag_by_long(name) {
                matcher.insert(flg.name);
            }
        }

        let used_arg = format!("--{}", arg);
        Err(err_unknown_argument(&used_arg, &suffix.0, &create_error_usage(self.app, matcher, None)))
    }

    fn parse_short_arg(&mut self, matcher: &mut Matches, full_arg: &str) -> ParseRes<ParseResult> {
        let arg = full_arg.trim_start_matches('-');

        let mut ret = ParseResult::NotFound;
        for c in arg.chars() {
            if let Some(opt) = self.app.find_opt_by_short(c).cloned() {
                // Check for trailing concatenated value
                let p: Vec<&str> = arg.splitn(2, c).collect();
                let val = if !p[1].is_empty() { Some(p[1]) } else { None };
                let ret = self.parse_opt(val, &opt, matcher);
                return Ok(ret);
            } else if let Some(flag) = self.app.find_flag_by_short(c).cloned() {
                self.check_for_help_and_version_char(c)?;
                ret = self.parse_flag(&flag, matcher);
            } else {
                let arg = format!("-{}", c);
                return Err(err_unknown_argument(&arg, "", &create_error_usage(self.app, matcher, None)));
            }
        }
        Ok(ret)
    }

    fn parse_help_subcommand<I: Iterator<Item = String>>(&self, it: &mut I) -> ParseRes<()> {
        let cmds: Vec<String> = it.collect();
        let mut help_help = false;
        let mut bin_name = self.app.display_name().to_owned();
        let mut sc: App = self.app.clone();
        for cmd in cmds.iter() {
            if cmd == "help" {
                help_help = true;
            }
            match sc.subcommands.iter().find(|s| &s.name == cmd).cloned() {
                Some(c) => {
                    sc = c;
                }
                None => {
                    return Err(err_unrecognized_subcommand(cmd, self.app.display_name()));
                }
            }
            bin_name = format!("{} {}", bin_name, sc.name);
        }
        if help_help {
            let mut pb = Arg::new("subcommand").positional();
            pb.help = Some("The subcommand whose help message to display");
            pb.multiple = true;
            sc.args.push(pb);
        } else {
            sc.create_help_and_version();
        }
        sc.bin_name = Some(bin_name);
        Err(Exit::stdout(render_help(&sc, false)))
    }

    fn get_matches_with<I: Iterator<Item = String>>(&mut self, matcher: &mut Matches, it: &mut Peekable<I>) -> ParseRes<()> {
        self.app.create_help_and_version();
        let has_args = self.app.has_args();

        let mut subcmd_name: Option<String> = None;
        let mut needs_val_of: ParseResult = ParseResult::NotFound;
        let mut pos_counter = 1;

        while let Some(arg_os) = it.next() {
            let arg_os = arg_os.as_str();
            let starts_new_arg = self.is_new_arg(arg_os, needs_val_of);
            if !self.trailing_values && arg_os == "--" && starts_new_arg {
                self.trailing_values = true;
                continue;
            }

            if !self.trailing_values {
                match needs_val_of {
                    ParseResult::Opt(_) => (),
                    _ => {
                        if let Some(sc_name) = self.possible_subcommand(arg_os) {
                            if sc_name == "help" {
                                self.parse_help_subcommand(it)?;
                            }
                            subcmd_name = Some(sc_name);
                            break;
                        }
                    }
                }

                if starts_new_arg {
                    if arg_os.starts_with("--") {
                        needs_val_of = self.parse_long_arg(matcher, arg_os)?;
                        match needs_val_of {
                            ParseResult::Flag | ParseResult::Opt(..) | ParseResult::ValuesDone => continue,
                            _ => (),
                        }
                    } else if arg_os.starts_with('-') && arg_os.len() != 1 {
                        needs_val_of = self.parse_short_arg(matcher, arg_os)?;
                        continue;
                    }
                } else if let ParseResult::Opt(name) = needs_val_of {
                    let arg = self.app.find_arg(name).cloned().expect("internal error");
                    needs_val_of = self.add_val_to_arg(&arg, arg_os, matcher);
                    continue;
                }
            }

            if let Some(cdate) = did_you_mean(arg_os, self.sc_names()) {
                return Err(err_invalid_subcommand(
                    arg_os,
                    cdate,
                    self.app.display_name(),
                    &create_error_usage(self.app, matcher, None),
                ));
            }

            let positionals: Vec<Arg> = self.app.positionals().cloned().collect();
            if let Some(p) = positionals.get(pos_counter - 1) {
                let _ = self.add_val_to_arg(p, arg_os, matcher);
                matcher.inc_occurrence_of(p.name);
                if !p.multiple {
                    pos_counter += 1;
                }
            } else if !has_args {
                if let Some(cdate) = did_you_mean(arg_os, self.sc_names()) {
                    return Err(err_invalid_subcommand(
                        arg_os,
                        cdate,
                        self.app.display_name(),
                        &create_error_usage(self.app, matcher, None),
                    ));
                } else {
                    return Err(err_unrecognized_subcommand(arg_os, self.app.display_name()));
                }
            } else {
                return Err(err_unknown_argument(arg_os, "", &create_error_usage(self.app, matcher, None)));
            }
        }

        if let Some(ref pos_sc_name) = subcmd_name {
            let parent_bin = self.app.display_name().to_owned();
            let sc = self.app.subcommands.iter_mut().find(|s| &s.name == pos_sc_name).expect("internal error");
            let mut sc_matcher = Matches::default();
            sc.bin_name = Some(format!("{} {}", parent_bin, sc.name));
            let mut sub_parser = Parser { app: sc, trailing_values: false };
            sub_parser.get_matches_with(&mut sc_matcher, it)?;
            matcher.subcommand = Some((pos_sc_name.clone(), Box::new(sc_matcher)));
        } else if self.app.subcommand_required_else_help {
            return Err(Exit::error(render_help(self.app, false)));
        }

        self.validate(needs_val_of, matcher)
    }

    fn validate(&self, needs_val_of: ParseResult, matcher: &mut Matches) -> ParseRes<()> {
        let mut reqs_validated = false;
        if let ParseResult::Opt(a) = needs_val_of {
            let o = self.app.find_arg(a).expect("internal error");
            self.validate_required(matcher)?;
            reqs_validated = true;
            let should_err = match matcher.get(o.name) {
                Some(v) => v.vals.is_empty(),
                None => true,
            };
            if should_err {
                return Err(err_empty_value(o, &create_error_usage(self.app, matcher, None)));
            }
        }

        if !reqs_validated {
            self.validate_required(matcher)?;
        }
        self.validate_matched_args(matcher)?;
        Ok(())
    }

    fn validate_required(&self, matcher: &Matches) -> ParseRes<()> {
        for arg in self.app.args.iter().filter(|a| a.required) {
            if !matcher.contains(arg.name) {
                return self.missing_required_error(matcher);
            }
        }
        Ok(())
    }

    fn missing_required_error(&self, matcher: &Matches) -> ParseRes<()> {
        let c = Colorizer::for_stderr();
        let reqs: Vec<&str> = self.app.args.iter().filter(|a| a.required && !matcher.contains(a.name)).map(|a| a.name).collect();
        let req_args = get_required_usage_from(self.app, &reqs, Some(matcher))
            .iter()
            .fold(String::new(), |acc, s| acc + &format!("\n    {}", c.error(s)));
        Err(err_missing_required_argument(&req_args, &create_error_usage(self.app, matcher, None)))
    }

    fn validate_matched_args(&self, matcher: &Matches) -> ParseRes<()> {
        for (name, ma) in matcher.args.iter() {
            let arg = match self.app.find_arg(name) {
                Some(a) => a,
                None => continue,
            };
            if arg.is_opt() || arg.positional {
                self.validate_arg_num_vals(arg, ma, matcher)?;
            }
            if ma.occurs > 1 && !arg.multiple {
                return Err(err_unexpected_multiple_usage(arg, &create_error_usage(self.app, matcher, None)));
            }
        }
        Ok(())
    }

    fn validate_arg_num_vals(&self, a: &Arg, ma: &MatchedArg, matcher: &Matches) -> ParseRes<()> {
        if let Some(num) = a.num_vals {
            let should_err = if a.multiple { ma.vals.len() % num != 0 } else { num != ma.vals.len() };
            if should_err {
                let curr = if a.multiple { ma.vals.len() % num } else { ma.vals.len() };
                let suffix = if ma.vals.len() == 1 || (a.multiple && curr == 1) { "as" } else { "ere" };
                return Err(err_wrong_number_of_values(a, num, curr, suffix, &create_error_usage(self.app, matcher, None)));
            }
        }
        if a.takes_value && ma.vals.is_empty() {
            return Err(err_empty_value(a, &create_error_usage(self.app, matcher, None)));
        }
        Ok(())
    }
}

/// Parses the process arguments, exiting on help/version/errors.
pub fn get_matches(mut app: App, args: Vec<String>) -> Matches {
    let mut it = args.into_iter();
    if let Some(name) = it.next() {
        let p = Path::new(&name);
        if let Some(f) = p.file_name() {
            if let Some(s) = f.to_str() {
                if app.bin_name.is_none() {
                    app.bin_name = Some(s.to_owned());
                }
            }
        }
    }
    let mut matcher = Matches::default();
    let mut parser = Parser { app: &mut app, trailing_values: false };
    if let Err(e) = parser.get_matches_with(&mut matcher, &mut it.peekable()) {
        e.exit();
    }
    matcher
}
