/// Error used for topic parsing (mirrors the fixed hash parsing errors).
#[derive(Debug)]
enum HashParseError {
    InvalidHexCharacter(char, usize),
    InvalidHexLength,
}

impl fmt::Display for HashParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HashParseError::InvalidHexCharacter(c, i) => write!(f, "Invalid character {:?} at position {}", c, i),
            HashParseError::InvalidHexLength => write!(f, "Invalid input length"),
        }
    }
}

