/// Lazily decodes hex byte pairs, skipping whitespace.
struct HexPairs<'a> {
    inner: &'a str,
    iter: std::iter::Enumerate<std::str::Bytes<'a>>,
}

impl<'a> Iterator for HexPairs<'a> {
    type Item = Result<u8, HashParseError>;

    fn next(&mut self) -> Option<Self::Item> {
        let mut modulus = 0;
        let mut buf = 0u8;
        for (idx, byte) in self.iter.by_ref() {
            buf <<= 4;
            match byte {
                b'A'..=b'F' => buf |= byte - b'A' + 10,
                b'a'..=b'f' => buf |= byte - b'a' + 10,
                b'0'..=b'9' => buf |= byte - b'0',
                b' ' | b'\r' | b'\n' | b'\t' => {
                    buf >>= 4;
                    continue;
                }
                _ => {
                    let ch = self.inner[idx..].chars().next().unwrap();
                    return Some(Err(HashParseError::InvalidHexCharacter(ch, idx)));
                }
            }
            modulus += 1;
            if modulus == 2 {
                return Some(Ok(buf));
            }
        }
        match modulus {
            0 => None,
            _ => Some(Err(HashParseError::InvalidHexLength)),
        }
    }
}

fn parse_h256(input: &str) -> Result<[u8; 32], HashParseError> {
    let input = input.strip_prefix("0x").unwrap_or(input);
    let mut iter = HexPairs { inner: input, iter: input.bytes().enumerate() };
    let mut result = [0u8; 32];
    for byte in result.iter_mut() {
        *byte = iter.next().ok_or(HashParseError::InvalidHexLength)??;
    }
    if iter.next().is_some() {
        return Err(HashParseError::InvalidHexLength);
    }
    Ok(result)
}

fn load_function(path: &str, name_or_signature: &str) -> anyhow::Result<Function> {
    let file = File::open(path)?;
    let contract = Contract::load(file)?;
    let params_start = name_or_signature.find('(');

    match params_start {
        // It's a signature
        Some(params_start) => {
            let name = &name_or_signature[..params_start];

            contract
                .functions_by_name(name)?
                .iter()
                .find(|f| f.signature() == name_or_signature)
                .cloned()
                .ok_or_else(|| anyhow!("invalid function signature `{}`", name_or_signature))
        }

        // It's a name
        None => {
            let functions = contract.functions_by_name(name_or_signature)?;
            match functions.len() {
                0 => unreachable!(),
                1 => Ok(functions[0].clone()),
                _ => Err(anyhow!(
                    "More than one function found for name `{}`, try providing the full signature",
                    name_or_signature
                )),
            }
        }
    }
}

fn load_event(path: &str, name_or_signature: &str) -> anyhow::Result<Event> {
    let file = File::open(path)?;
    let contract = Contract::load(file)?;
