            true => LenientTokenizer::tokenize(param, value),
            false => StrictTokenizer::tokenize(param, value),
        })
        .collect::<Result<_, _>>()
        .map_err(From::from)
}

fn encode_input(path: &str, function: &str, values: &[String], lenient: bool) -> anyhow::Result<String> {
    let function = load_function(path, function)?;

    let params: Vec<_> =
        function.inputs.iter().map(|param| param.kind.clone()).zip(values.iter().map(|v| v as &str)).collect();

    let tokens = parse_tokens(&params, lenient)?;
    let result = function.encode_input(&tokens)?;

    Ok(hex::encode(result))
}

fn encode_params(params: &[String], lenient: bool) -> anyhow::Result<String> {
    assert_eq!(params.len() % 2, 0);

    let params = params
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .chunks(2)
        .map(|chunk| Reader::read(chunk[0]).map(|p| (p, chunk[1])))
        .collect::<Result<Vec<_>, _>>()?;

    let tokens = parse_tokens(&params, lenient)?;
    let result = encode(&tokens);

    Ok(hex::encode(result))
}

fn decode_call_output(path: &str, function: &str, data: &str) -> anyhow::Result<String> {
    let function = load_function(path, function)?;
    let data: Vec<u8> = hex::decode(data)?;
    let tokens = function.decode_output(&data)?;
    let types = function.outputs;

    assert_eq!(types.len(), tokens.len());

    let result =
        types.iter().zip(tokens.iter()).map(|(ty, to)| format!("{} {}", ty.kind, to)).collect::<Vec<String>>().join("\n");

    Ok(result)
}

fn decode_params(types: &[String], data: &str) -> anyhow::Result<String> {
    let types: Vec<ParamType> = types.iter().map(|s| Reader::read(s)).collect::<Result<_, _>>()?;

    let data: Vec<u8> = hex::decode(data)?;

    let tokens = decode(&types, &data)?;

    assert_eq!(types.len(), tokens.len());

    let result = types.iter().zip(tokens.iter()).map(|(ty, to)| format!("{} {}", ty, to)).collect::<Vec<String>>().join("\n");

    Ok(result)
}

fn decode_log(path: &str, event: &str, topics: &[String], data: &str) -> anyhow::Result<String> {
    let event = load_event(path, event)?;
    let topics: Vec<[u8; 32]> = topics.iter().map(|t| parse_h256(t)).collect::<Result<_, _>>()?;
    let data = hex::decode(data)?;
    let decoded = event.parse_log(topics, data)?;

    let result = decoded.into_iter().map(|log_param| format!("{} {}", log_param.name, log_param.value)).collect::<Vec<String>>().join("\n");

    Ok(result)
}

fn execute(matches: &Matches) -> anyhow::Result<String> {
    match matches.subcommand() {
        Some(("encode", m)) => match m.subcommand() {
            Some(("function", f)) => {
                let path = f.value_of("abi-path").unwrap_or("");
                let name = f.value_of("function-name-or-signature").unwrap_or("");
                let params = f.values_of("params");
                encode_input(path, name, &params, f.is_present("lenient"))
            }
            Some(("params", p)) => encode_params(&p.values_of("params"), p.is_present("lenient")),
            _ => unreachable!(),
        },
        Some(("decode", m)) => match m.subcommand() {
            Some(("function", f)) => {
                let path = f.value_of("abi-path").unwrap_or("");
                let name = f.value_of("function-name-or-signature").unwrap_or("");
                let data = f.value_of("data").unwrap_or("");
                decode_call_output(path, name, data)
            }
            Some(("params", p)) => {
                let types = p.values_of("types");
                decode_params(&types, p.value_of("data").unwrap_or(""))
            }
            Some(("log", l)) => {
                let path = l.value_of("abi-path").unwrap_or("");
                let name = l.value_of("event-name-or-signature").unwrap_or("");
                let topics = l.values_of("topics");
                decode_log(path, name, &topics, l.value_of("data").unwrap_or(""))
            }
            _ => unreachable!(),
        },
        _ => unreachable!(),
    }
}

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let matches = clap2::get_matches(build_app(), args);
    let result = execute(&matches)?;
    println!("{}", result);
    Ok(())
}
