    let data = hex::decode(data)?;
    let decoded = event.parse_log(topics, data)?;

    let result = decoded.into_iter().map(|log_param| format!("{} {}", log_param.name, log_param.value)).collect::<Vec<String>>().join("\n");

    Ok(result)
}

fn execute(matches: &Matches) -> anyhow::Result<String> {
    match matches.subcommand() {
        Some(("encode", m)) => match m.subcommand() {
            Some(("function", f)) => {
                let path = f.value_of("abi-path").unwrap_or("");
                let name = f.value_of("function-name-or-signature").unwrap_or("");
                let params = f.values_of("params");
                encode_input(path, name, &params, f.is_present("lenient"))
            }
            Some(("params", p)) => encode_params(&p.values_of("params"), p.is_present("lenient")),
            _ => unreachable!(),
        },
        Some(("decode", m)) => match m.subcommand() {
            Some(("function", f)) => {
                let path = f.value_of("abi-path").unwrap_or("");
                let name = f.value_of("function-name-or-signature").unwrap_or("");
                let data = f.value_of("data").unwrap_or("");
                decode_call_output(path, name, data)
            }
            Some(("params", p)) => {
                let types = p.values_of("types");
                decode_params(&types, p.value_of("data").unwrap_or(""))
            }
            Some(("log", l)) => {
                let path = l.value_of("abi-path").unwrap_or("");
                let name = l.value_of("event-name-or-signature").unwrap_or("");
                let topics = l.values_of("topics");
                decode_log(path, name, &topics, l.value_of("data").unwrap_or(""))
            }
            _ => unreachable!(),
        },
        _ => unreachable!(),
    }
}

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let matches = clap2::get_matches(build_app(), args);
    let result = execute(&matches)?;
    println!("{}", result);
    Ok(())
}
