//! Error type of the ABI coder.

use std::fmt;

use crate::hex::FromHexError;
use crate::u256::FromDecStrErr;

/// Signed integer parse failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IntParseError {
    Overflow,
    Underflow,
}

/// ABI coder error.
#[derive(Debug)]
pub enum Error {
    /// Invalid entity such as a bad function name.
    InvalidName(String),
    /// Invalid data.
    InvalidData,
    /// Serialization error.
    SerdeJson(serde_json::Error),
    /// Integer parsing error.
    ParseInt(std::num::ParseIntError),
    /// Hex string parsing error.
    Hex(FromHexError),
    /// Decimal uint parsing error.
    Uint(FromDecStrErr),
    /// Decimal int parsing error.
    Int(IntParseError),
    /// Other errors.
    Other(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidName(name) => write!(f, "Invalid name: {}", name),
            Error::InvalidData => write!(f, "Invalid data"),
            Error::SerdeJson(e) => write!(f, "Serialization error: {}", e),
            Error::ParseInt(e) => write!(f, "Integer parsing error: {}", e),
            Error::Hex(e) => write!(f, "Hex parsing error: {}", e),
            Error::Uint(e) => write!(f, "Uint parse error: {:?}", e),
            Error::Int(e) => write!(f, "int256 parse error: {:?}", e),
            Error::Other(s) => write!(f, "{}", s),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::SerdeJson(e) => Some(e),
            Error::ParseInt(e) => Some(e),
            Error::Hex(e) => Some(e),
            _ => None,
        }
    }
}

impl From<serde_json::Error> for Error {
    fn from(e: serde_json::Error) -> Self {
        Error::SerdeJson(e)
    }
}

impl From<std::num::ParseIntError> for Error {
    fn from(e: std::num::ParseIntError) -> Self {
        Error::ParseInt(e)
    }
}

impl From<FromHexError> for Error {
    fn from(e: FromHexError) -> Self {
        Error::Hex(e)
    }
}

impl From<FromDecStrErr> for Error {
    fn from(e: FromDecStrErr) -> Self {
        Error::Uint(e)
    }
}

pub type Result<T> = std::result::Result<T, Error>;
